-- =====================================================================
-- RipassoAI — 0010: 20 domande fondamentali in più per JavaScript
--   * passa da 30 a 50 domande approvate per l'argomento javascript
--   * 4 L1, 6 L2, 6 L3, 4 L4
--   * idempotente: importa_quiz salta i testi già presenti
-- =====================================================================

select public.importa_quiz('javascript', $j$[
  {"livello":"L1","testo":"Quale sintassi permette di inserire un'espressione dentro un template literal?","spiegazione":"I template literal usano i backtick e ${...} per interpolare espressioni; le altre sintassi non sono JavaScript.","opzioni":["${espressione}","#{espressione}","{{espressione}}","[espressione]"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo aggiunge una classe a un elemento senza sovrascrivere le classi esistenti?","spiegazione":"classList.add modifica solo la classe indicata; className = '...' sostituisce l'intero attributo class.","opzioni":["element.style.class = 'attiva'","element.classList.add('attiva')","element.className = 'attiva'","element.setAttribute('class', 'attiva')"],"corretta":1},
  {"livello":"L1","testo":"Quale proprietà indica se una checkbox è selezionata?","spiegazione":"La proprietà checked è un booleano che riflette lo stato della casella; value contiene il valore da inviare.","opzioni":["selected","disabled","checked","value"],"corretta":2},
  {"livello":"L1","testo":"Quale operatore restituisce il resto di una divisione?","spiegazione":"% calcola il resto (modulo). / restituisce il quoziente, * moltiplica e ** eleva a potenza.","opzioni":["/","*","**","%"],"corretta":3},
  {"livello":"L2","testo":"Cosa accade se si legge una variabile let prima della dichiarazione nello stesso blocco?","spiegazione":"let e const sono soggetti alla temporal dead zone: il binding esiste ma non è inizializzato fino alla dichiarazione, quindi si ottiene un ReferenceError.","opzioni":["Vale 0","Si ottiene un ReferenceError per la temporal dead zone","Vale undefined","Vale null"],"corretta":1},
  {"livello":"L2","testo":"Qual è la differenza tra spread e rest?","spiegazione":"Lo spread espande elementi in un nuovo contesto; il rest raccoglie più valori in un array o in un oggetto. Usano la stessa sintassi ... ma in posizioni diverse.","opzioni":["Lo spread funziona solo con gli array","Il rest funziona solo con gli oggetti","Lo spread espande elementi, il rest raccoglie argomenti o proprietà","Sono due nomi per la stessa cosa"],"corretta":2},
  {"livello":"L2","testo":"Cosa permette il destructuring di un oggetto?","spiegazione":"Permette di estrarre proprietà in variabili con una sintassi compatta: const { nome, eta } = utente. Non crea una copia profonda né congela l'oggetto.","opzioni":["Creare una copia profonda automatica","Congelare l'oggetto","Serializzare l'oggetto in JSON","Estrarre proprietà in variabili con una sintassi compatta"],"corretta":3},
  {"livello":"L2","testo":"Cosa restituisce l'espressione a && b quando a è falsy?","spiegazione":"&& corto-circuita: se il primo operando è falsy lo restituisce e non valuta il secondo. Restituisce b solo quando a è truthy.","opzioni":["Restituisce a, senza valutare b","Restituisce sempre false","Restituisce b","Lancia un errore"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve il blocco finally in try/catch/finally?","spiegazione":"finally esegue sempre, sia quando il try termina normalmente sia quando viene lanciato un errore, ed è utile per chiudere risorse.","opzioni":["Esegue solo se non ci sono errori","Rilancia l'errore precedente","Esegue codice sempre, con o senza errore","Esegue solo se c'è un errore"],"corretta":2},
  {"livello":"L2","testo":"Cosa restituisce sempre una funzione dichiarata con async?","spiegazione":"Una funzione async restituisce sempre una Promise: il valore di return diventa il valore risolto, un throw diventa un rifiuto.","opzioni":["Il valore restituito direttamente","undefined","Un callback","Una Promise"],"corretta":3},
  {"livello":"L3","testo":"Quale metodo attende più Promise e si rifiuta al primo errore?","spiegazione":"Promise.all fallisce appena una delle Promise si rifiuta; Promise.allSettled invece attende tutte e riporta ogni esito.","opzioni":["Promise.all","Promise.allSettled","Promise.race","Promise.any"],"corretta":0},
  {"livello":"L3","testo":"Cosa restituisce Promise.allSettled per ogni Promise?","spiegazione":"Per ogni Promise restituisce un oggetto con status 'fulfilled' e value, oppure status 'rejected' e reason, senza interrompere le altre.","opzioni":["Il primo errore incontrato","Un oggetto con status e value oppure reason","Solo il valore della prima Promise risolta","Un booleano"],"corretta":1},
  {"livello":"L3","testo":"Come si applica la delega degli eventi a una lista dinamica?","spiegazione":"Si aggiunge un solo listener al contenitore e si risale dal target con closest(): così funzionano anche gli elementi creati dopo.","opzioni":["Un listener su ogni elemento creato","Un onclick inline su ogni voce","Un setInterval che controlla i click","Un solo listener sul contenitore e event.target.closest(...)"],"corretta":3},
  {"livello":"L3","testo":"Perché si usa l'evento DOMContentLoaded?","spiegazione":"DOMContentLoaded scatta quando il parsing dell'HTML è terminato; l'evento load attende anche immagini, fogli di stile e altre risorse.","opzioni":["Per eseguire lo script dopo che il DOM è stato costruito","Per attendere il caricamento di tutte le immagini","Per eseguire lo script prima dell'HTML","Per attivare il rendering GPU"],"corretta":0},
  {"livello":"L3","testo":"Qual è la differenza principale tra localStorage e sessionStorage?","spiegazione":"localStorage conserva i dati anche dopo la chiusura della scheda; sessionStorage dura quanto la sessione della scheda. Entrambi salvano stringhe e sono sincroni.","opzioni":["Solo localStorage accetta stringhe","localStorage persiste alla chiusura della scheda, sessionStorage no","sessionStorage è più capiente","localStorage è sincrono e sessionStorage asincrono"],"corretta":1},
  {"livello":"L3","testo":"Come si esporta un valore come export predefinito di un modulo ES?","spiegazione":"Si usa export default valore; module.exports appartiene a CommonJS, mentre export = e default export non sono sintassi ES valide.","opzioni":["export = valore","default export valore","export default valore","module.exports = valore"],"corretta":2},
  {"livello":"L4","testo":"Cosa garantisce Object.freeze su un oggetto?","spiegazione":"Impedisce aggiunte e modifiche alle proprietà di primo livello; gli oggetti annidati restano mutabili, quindi non è una copia profonda immutabile.","opzioni":["Impedisce aggiunte e modifiche alle proprietà di primo livello","Crea una copia profonda immutabile","Blocca anche la mutazione degli oggetti annidati","Serializza l'oggetto"],"corretta":0},
  {"livello":"L4","testo":"Qual è la differenza tra copia superficiale e copia profonda?","spiegazione":"La copia superficiale duplica il primo livello ma condivide i riferimenti annidati; quella profonda duplica ricorsivamente anche gli oggetti interni.","opzioni":["La copia profonda copia solo il primo livello","Sono identiche","La copia superficiale condivide i riferimenti annidati, quella profonda li duplica","La copia superficiale duplica tutto"],"corretta":2},
  {"livello":"L4","testo":"Qual è la differenza tra throttle e debounce?","spiegazione":"Throttle esegue al massimo una volta ogni intervallo; debounce posticipa l'esecuzione finché gli eventi continuano ad arrivare.","opzioni":["Sono la stessa cosa","Throttle limita la frequenza, debounce esegue dopo una pausa","Debounce limita la frequenza, throttle esegue dopo una pausa","Entrambi eseguono una sola volta"],"corretta":1},
  {"livello":"L4","testo":"Perché setTimeout(fn, 0) non esegue fn immediatamente?","spiegazione":"Il callback viene accodato come macrotask: dopo il codice sincrono vengono svuotati i microtask e solo poi il timer viene eseguito.","opzioni":["Perché il timer minimo è 1000 ms","Perché fn viene ignorata","Perché funziona solo nel browser","Il callback va in coda come macrotask e attende che si svuotino i microtask"],"corretta":3}
]$j$::jsonb);
